SEGS = lambda id,lbl,items: '<div class="ctl"><span class="lbl">%s</span><div class="seg" id="%s" role="group" aria-label="%s">' % (lbl,id,lbl) + ''.join('<button type="button" data-k="%s" aria-pressed="%s">%s</button>' % (k,'true' if i==0 else 'false',t) for i,(k,t) in enumerate(items)) + '</div></div>'

mod('meiosis','Meiosis & genetic variation',
 'Sexual reproduction mixes genes from two parents. Meiosis is the cell division that halves the chromosome number and shuffles the genes so that no two gametes are alike.',
 ['A diploid cell (2n) has two copies of each chromosome, one from each parent (<b>homologous chromosomes</b>). Meiosis makes <b>haploid</b> (n) gametes with one copy of each. After DNA replication, <b>meiosis I</b> separates the <i>homologs</i> (so the cells become haploid) and <b>meiosis II</b> separates the <i>sister chromatids</i> (like mitosis). One diploid cell yields <b>four</b> genetically different haploid cells.',
  'Variation comes from three sources. <b>Crossing over</b> in prophase I swaps pieces between homologs, making new combinations of alleles on one chromosome. <b>Independent assortment</b> in metaphase I: each homologous pair lines up at random, so with n pairs there are 2<sup>n</sup> possible combinations (over 8 million in humans). <b>Random fertilization</b> then combines any egg with any sperm. Errors in separation (<b>nondisjunction</b>) produce gametes with extra or missing chromosomes, as in trisomy 21.'],
 ('cell division always made identical copies','that a special division halves the chromosome number and creates variation','why siblings differ and how chromosome number stays constant across generations','meiosis I and II, crossing over and independent assortment'),
 [('2n → n (meiosis I) → n (meiosis II)','one cell → four cells'),('possible gametes (no crossing over) = 2ⁿ','n = haploid number'),('zygote: n + n = 2n','fertilization'),('meiosis I separates homologs; meiosis II separates sister chromatids','key difference from mitosis')],
 [stagelab('me2-lab','Meiosis step by step',canvas='me2-canvas',aria='A cell with four chromosomes (two homologous pairs) shown at each stage of meiosis I and II.',p='ms',n=7,out_extra=[('ms-n','chromosome number per cell','a')]),
  lab('me2-lab2','How many different gametes?',canvas='me2-canvas2',aria='A bar showing the number of possible chromosome combinations in gametes as the number of chromosome pairs increases.',
   ctl=[('ms-pairs','Chromosome pairs (n)',1,23,1,3)],
   out=[('ms-g','different gametes (no crossing over)','x'),('ms-z','different zygotes from two such parents','a')],own=True)],
 [('Go to anaphase I. What separates? <button type="button" class="btn link" data-show=\'' + show(["#ms-st",3]) + '\'>Set it up for me</button>','','The homologous chromosomes separate. Sister chromatids stay together, which is why cells after meiosis I are haploid.'),
  ('Set n = 23. How many gametes are possible? <button type="button" class="btn link" data-show=\'' + show(["#ms-pairs",23]) + '\'>Set it up for me</button>','','2²³ = 8,388,608 different combinations of maternal and paternal chromosomes, before crossing over is counted.')],
 ('A fruit fly has 2n = 8. How many different gametes are possible from independent assortment alone, and how many chromosomes are in each gamete?',[
  '<b>Haploid number.</b> n = 8/2 = 4 pairs.',
  '<b>Combinations.</b> 2<sup>4</sup> = 16 different gametes.',
  '<b>Each gamete.</b> 4 chromosomes (one from each pair).']),
 ['Saying meiosis I separates sister chromatids.','Saying meiosis makes two cells.','Counting chromosomes by chromatids: after meiosis I each cell has n chromosomes, each with two chromatids.','Mixing up crossing over (within a pair) and independent assortment (between pairs).','Believing meiosis II halves the chromosome number again.'],
 ('Compare mitosis and meiosis',['Mitosis: one division, two identical diploid cells, for growth and repair. Meiosis: two divisions, four different haploid cells, for gametes. Only meiosis has synapsis, crossing over and separation of homologs.']),
 [('Which event in meiosis directly creates new combinations of alleles on the same chromosome?',['crossing over in prophase I','independent assortment in metaphase I','separation of sister chromatids','fertilization'],0,'Crossing over exchanges segments between homologous chromosomes.')])

mod('mendel','Mendelian inheritance',
 'Offspring get one allele for each gene from each parent. With a Punnett square you can predict the odds before anything is born.',
 ['Mendel\'s <b>law of segregation</b>: the two alleles for a gene separate into different gametes, so each gamete carries one. A <b>dominant</b> allele shows when present; a <b>recessive</b> allele shows only in two copies. <b>Genotype</b> is the allele combination (AA, Aa, aa); <b>phenotype</b> is the observable trait. A cross of two heterozygotes (Aa × Aa) gives genotypes 1 AA : 2 Aa : 1 aa and phenotypes 3 dominant : 1 recessive.',
  'The <b>law of independent assortment</b>: genes on different chromosomes are inherited independently, so AaBb × AaBb gives a 9 : 3 : 3 : 1 phenotype ratio. A <b>test cross</b> (unknown × homozygous recessive) reveals an unknown genotype. Use the <b>product rule</b> (and) and the <b>sum rule</b> (or) for probabilities. Real counts only approximate the ratios, which is where the chi-square test comes in.'],
 ('traits blended in offspring','that discrete alleles are inherited from each parent and can hide for a generation','how to predict ratios and probabilities for crosses','Punnett squares, genotype vs phenotype, and ratios'),
 [('Aa × Aa → 1 AA : 2 Aa : 1 aa','genotypes'),('3 dominant : 1 recessive','phenotypes'),('AaBb × AaBb → 9 : 3 : 3 : 1','dihybrid'),('P(A and B) = P(A) × P(B); P(A or B) = P(A) + P(B)','product and sum rules')],
 [lab('md-lab','Punnett square: one gene',canvas='md-canvas',aria='A Punnett square for the chosen parent genotypes, with the offspring genotype and phenotype ratios.',
   pre=SEGS('md-p1','Parent 1',[('AA','AA'),('Aa','Aa'),('aa','aa')]) + SEGS('md-p2','Parent 2',[('AA','AA'),('Aa','Aa'),('aa','aa')]) + '<div class="row"><button type="button" class="btn" id="md-go">Make 100 offspring</button></div>',
   out=[('md-gt','genotype ratio','x'),('md-pt','phenotype ratio (dominant : recessive)','a'),('md-obs','100 random offspring','v')],own=True),
  lab('md-lab2','Two genes at once (AaBb × AaBb)',canvas='md-canvas2',aria='A sixteen-square grid. Each square is a possible offspring, coloured by phenotype.',
   seg=('md-hl','Highlight',[('all','all'),('AB','dominant for both'),('Ab','dominant A, recessive b'),('aB','recessive a, dominant B'),('ab','recessive for both')]),
   out=[('md-n','squares highlighted (of 16)','x'),('md-r','fraction','a')],own=True)],
 [('Set both parents to Aa. What phenotype ratio results? <button type="button" class="btn link" data-show=\'' + show(["click","#md-p1 [data-k=Aa]"],["click","#md-p2 [data-k=Aa]"]) + '\'>Set it up for me</button>','','3 dominant : 1 recessive (genotypes 1 AA : 2 Aa : 1 aa).'),
  ('Make parent 1 Aa and parent 2 aa (a test cross). What do you see? <button type="button" class="btn link" data-show=\'' + show(["click","#md-p1 [data-k=Aa]"],["click","#md-p2 [data-k=aa]"]) + '\'>Set it up for me</button>','','1 : 1 for both genotype and phenotype. A homozygous dominant parent would instead give all dominant offspring.'),
  ('Highlight "recessive for both". What fraction of the 16? <button type="button" class="btn link" data-show=\'' + show(["click","#md-hl [data-k=ab]"]) + '\'>Set it up for me</button>','','1/16. The four classes are 9 : 3 : 3 : 1.')],
 ('In pea plants purple (P) is dominant to white (p). Two heterozygous purple plants are crossed. What is the probability that the first two offspring are both white?',[
  '<b>One offspring.</b> Pp × Pp gives 1/4 pp (white).',
  '<b>Product rule.</b> P(both white) = 1/4 × 1/4.',
  '<b>Answer.</b> 1/16 = 0.0625 (6.25%). Offspring are independent events, so earlier results do not change later odds.']),
 ['Saying the "ratio" must appear exactly in real data.','Thinking a family with three dominant children makes the next child likely recessive.','Mixing up genotype and phenotype ratios.','Forgetting each parent contributes one allele.','Using the sum rule when "and" requires the product rule.'],
 ('Reading a cross',['First write the parent genotypes (use the phenotype of offspring to infer them). Then list gametes, fill the square, and count. For two genes, treat each separately and multiply: P(AaBb) = P(Aa) × P(Bb). Give answers as ratios or probabilities as asked.']),
 [('Two parents are both Aa. What fraction of their offspring is expected to show the recessive phenotype?',['1/4','1/2','3/4','0'],0,'Only aa shows the recessive phenotype: 1 of 4.')])

mod('nonmendel','Beyond simple dominance',
 'Not every trait is a simple dominant-recessive pair. Alleles can blend, share, or be hidden by other genes.',
 ['<b>Incomplete dominance</b>: the heterozygote is intermediate (red × white snapdragons give pink; a 1 : 2 : 1 phenotype ratio in the next generation). <b>Codominance</b>: both alleles are fully expressed (AB blood type; a roan coat with both red and white hairs). <b>Multiple alleles</b>: a population can have more than two alleles of a gene (ABO blood: I<sup>A</sup>, I<sup>B</sup> and i; A and B are codominant, i is recessive).',
  '<b>Polygenic traits</b> depend on many genes and show a continuous range (height, skin colour) that forms a bell-shaped curve. <b>Epistasis</b>: one gene masks the expression of another (in labrador coat colour the gene for pigment deposition can hide the gene for pigment colour, giving 9 : 3 : 4). The <b>environment</b> also affects phenotype (hydrangea colour depends on soil pH). These patterns still follow Mendel\'s rules for how alleles are inherited; they differ in how alleles combine to make the phenotype.'],
 ('every heterozygote looked like one of its parents','that alleles can share or blend expression, and genes can interact','why ratios are sometimes 1 : 2 : 1 or 9 : 3 : 4 instead of 3 : 1','incomplete dominance, codominance, multiple alleles, polygenic traits, epistasis'),
 [('incomplete dominance: 1 : 2 : 1 phenotype','heterozygote intermediate'),('codominance: both alleles show','AB blood type'),('epistasis: 9 : 3 : 4','one gene masks another'),('polygenic: bell curve','many genes, many small effects')],
 [lab('nm-lab','Cross two heterozygotes',canvas='nm-canvas',aria='Bar graph of the expected phenotype ratio when two heterozygous parents are crossed, for the chosen pattern of inheritance.',
   seg=('nm-pat','Inheritance pattern',[('cd','complete dominance'),('id','incomplete dominance'),('co','codominance'),('ep','epistasis (two genes)')]),
   out=[('nm-gt','genotype ratio','x'),('nm-pt','phenotype ratio','a'),('nm-ex','example','')],own=True),
  lab('nm-lab2','ABO blood types of children',canvas='nm-canvas2',aria='Bars showing the probability of each blood type for children of the chosen parents.',
   pre=SEGS('nm-b1','Parent 1',[('IAIA','IᴬIᴬ (A)'),('IAi','Iᴬi (A)'),('IBIB','IᴮIᴮ (B)'),('IBi','Iᴮi (B)'),('IAIB','IᴬIᴮ (AB)'),('ii','ii (O)')]) + SEGS('nm-b2','Parent 2',[('IAIA','IᴬIᴬ (A)'),('IAi','Iᴬi (A)'),('IBIB','IᴮIᴮ (B)'),('IBi','Iᴮi (B)'),('IAIB','IᴬIᴮ (AB)'),('ii','ii (O)')]),
   out=[('nm-bt','possible blood types','x'),('nm-bp','probabilities','a')],own=True)],
 [('Choose incomplete dominance. What fraction of the offspring look like the heterozygote? <button type="button" class="btn link" data-show=\'' + show(["click","#nm-pat [data-k=id]"]) + '\'>Set it up for me</button>','','1/2 (the Aa genotype), and phenotypes are 1 : 2 : 1 instead of 3 : 1.'),
  ('Choose epistasis. What ratio appears? <button type="button" class="btn link" data-show=\'' + show(["click","#nm-pat [data-k=ep]"]) + '\'>Set it up for me</button>','','9 : 3 : 4. The 3 : 1 class and the 1 class that carry the masking genotype look identical (here, yellow).'),
  ('Cross IᴬIᴮ with ii. What types can the children have? <button type="button" class="btn link" data-show=\'' + show(["click","#nm-b1 [data-k=IAIB]"],["click","#nm-b2 [data-k=ii]"]) + '\'>Set it up for me</button>','','Half type A (Iᴬi) and half type B (Iᴮi). No child is AB or O.')],
 ('A man with blood type A (his mother was type O) and a woman with type B (her father was type O) have children. What are the parents\' genotypes and what types are possible?',[
  '<b>Man.</b> Type A, and he inherited i from his type O mother, so he is I<sup>A</sup>i.',
  '<b>Woman.</b> Type B, and she inherited i from her type O father, so she is I<sup>B</sup>i.',
  '<b>Cross.</b> I<sup>A</sup>i × I<sup>B</sup>i gives I<sup>A</sup>I<sup>B</sup> (AB), I<sup>A</sup>i (A), I<sup>B</sup>i (B) and ii (O), each 1/4. All four types are possible.']),
 ['Calling incomplete dominance a "blend that cannot separate again". The alleles are still inherited separately, and red and white reappear in the next generation.','Thinking codominance and incomplete dominance are the same. In codominance both alleles show fully (distinct); in incomplete dominance the result is intermediate.','Saying a person has three ABO alleles. Each person has two; the population has three.','Thinking polygenic traits break Mendel\'s laws.','Missing that epistasis changes the 9 : 3 : 3 : 1 ratio.'],
 ('Matching ratios to patterns',['3 : 1 → simple dominance. 1 : 2 : 1 → incomplete dominance or codominance from a heterozygote cross. 9 : 3 : 4 (or 9 : 7, 12 : 3 : 1) → epistasis. A continuous range with a bell curve → polygenic with environment effects.']),
 [('A cross of two pink snapdragons (incomplete dominance) gives which phenotype ratio?',['1 red : 2 pink : 1 white','3 red : 1 white','all pink','1 : 1'],0,'Heterozygotes cross to give 1 : 2 : 1, and each genotype has its own phenotype.')])

mod('sexlink','Sex linkage & pedigrees',
 'Genes on the X chromosome behave differently in males and females, because males have only one X.',
 ['Females are XX and males are XY. A gene on the X chromosome with no matching gene on the Y is <b>X-linked</b>. Males have one allele, so a single recessive allele (for red-green color blindness or hemophilia) shows. Females need two. A <b>carrier</b> female (X<sup>H</sup>X<sup>h</sup>) is unaffected. Sons inherit their X only from their mother and their Y from the father, so X-linked traits are never passed from father to son, and fathers pass their X to all daughters.',
  'A <b>pedigree</b> is a family tree showing a trait (squares are males, circles are females, filled symbols are affected). Clues: <b>autosomal recessive</b>: two unaffected parents can have an affected child; both sexes equally affected. <b>Autosomal dominant</b>: every affected person has an affected parent; no skipped generations. <b>X-linked recessive</b>: many more affected males; affected males have unaffected father; passes through carrier daughters.'],
 ('all genes were inherited the same way in males and females','that males have a single X, so X-linked recessives show more often in males','how to read inheritance patterns from a family tree','X-linked crosses and pedigree patterns'),
 [('X-linked recessive: X<sup>h</sup>Y is affected, X<sup>H</sup>X<sup>h</sup> is a carrier','X<sup>h</sup>X<sup>h</sup> is affected'),('carrier mother × normal father → 1/2 of sons affected','no daughters affected'),('father to son: Y only, never X','so no father-to-son transmission'),('squares = males, circles = females, filled = affected','pedigree symbols')],
 [lab('sx-lab','X-linked cross',canvas='sx-canvas',aria='A Punnett square for an X-linked cross with the chosen mother and father.',
   pre=SEGS('sx-m','Mother',[('XHXH','XᴴXᴴ'),('XHXh','XᴴXʰ'),('XhXh','XʰXʰ')]) + SEGS('sx-f','Father',[('XHY','XᴴY'),('XhY','XʰY')]),
   out=[('sx-sons','sons affected','x'),('sx-dau','daughters affected / carriers','a')],own=True),
  lab('sx-lab2','Reading a pedigree',canvas='sx-canvas2',aria='A three-generation pedigree for the chosen inheritance pattern. Filled symbols are affected.',
   seg=('sx-pat','Pattern',[('ar','autosomal recessive'),('ad','autosomal dominant'),('xr','X-linked recessive')]),
   pre='<div class="row"><button type="button" class="btn" id="sx-gt" aria-pressed="false">Show genotypes</button></div>',
   out=[('sx-clue','clue','x'),('sx-note','what to look for','')],own=True)],
 [('Choose a carrier mother and a normal father. What are the odds for sons? <button type="button" class="btn link" data-show=\'' + show(["click","#sx-m [data-k=XHXh]"],["click","#sx-f [data-k=XHY]"]) + '\'>Set it up for me</button>','','1/2 of sons are affected (they got X<sup>h</sup>), 1/2 are normal. Half of daughters are carriers, none affected.'),
  ('Choose an affected father (XʰY) and a normal mother (XᴴXᴴ). <button type="button" class="btn link" data-show=\'' + show(["click","#sx-m [data-k=XHXH]"],["click","#sx-f [data-k=XhY]"]) + '\'>Set it up for me</button>','','No sons are affected (they get his Y); all daughters are carriers (they get his Xʰ).')],
 ('A woman who is a carrier for hemophilia (X-linked recessive) has children with an unaffected man. What is the probability that a child (sex unknown) has hemophilia?',[
  '<b>Cross.</b> X<sup>H</sup>X<sup>h</sup> × X<sup>H</sup>Y gives X<sup>H</sup>X<sup>H</sup>, X<sup>H</sup>X<sup>h</sup>, X<sup>H</sup>Y, X<sup>h</sup>Y.',
  '<b>Affected.</b> Only X<sup>h</sup>Y: 1 of 4.',
  '<b>Answer.</b> 1/4 (25%) for a child of unknown sex; for a son it is 1/2.']),
 ['Saying a father can pass an X-linked allele to his son.','Writing a recessive X-linked trait as if females were affected as often as males.','Mixing up carriers (unaffected) with affected females.','Reading a pedigree and forgetting the trait could be autosomal.','Forgetting the question might ask about the probability for a son vs for any child.'],
 ('Reading pedigrees',['Look first for two unaffected parents with an affected child: that points to recessive. Then ask whether more males are affected and whether affected males have unaffected fathers: that points to X-linked. Confirm by assigning genotypes and checking every mating.']),
 [('Hemophilia is X-linked recessive. A normal father and a carrier mother have a son. His chance of hemophilia is',['1/2','1/4','0','1'],0,'The son gets his mother\'s Xʰ with probability 1/2.')])

mod('linkage','Linked genes & recombination',
 'Genes on the same chromosome tend to travel together. How often they separate tells you how far apart they are.',
 ['Independent assortment only applies to genes on <b>different chromosomes</b>. Genes close together on the same chromosome are <b>linked</b>: they are inherited together unless <b>crossing over</b> between them breaks the pairing. The offspring with the original (parental) combinations are <b>parental types</b>; those with new combinations are <b>recombinants</b>.',
  'The <b>recombination frequency</b> = recombinants / total offspring × 100%. The farther apart two genes, the more often a crossover falls between them. By definition 1% recombination = 1 <b>map unit</b> (centimorgan). Recombination frequencies cannot exceed 50%; at 50% the genes behave as if unlinked. Distances from three genes let you order them on a chromosome. A <b>test cross</b> (AaBb × aabb) makes recombinants easy to count because the recessive parent contributes only recessive alleles.'],
 ('genes were always independent','that genes on one chromosome move together unless crossing over separates them','how crossover frequency gives distance and gene order','linkage, recombination frequency and map units'),
 [('recombination frequency = recombinants / total × 100%','map units'),('1% recombination = 1 map unit','centimorgan'),('maximum observed recombination = 50%','looks unlinked'),('parental types are most common if genes are linked','in a test cross')],
 [lab('lk-lab','Test cross of two linked genes',canvas='lk-canvas',aria='A chromosome with two genes the chosen number of map units apart and bars showing expected numbers of parental and recombinant offspring from a test cross.',
   ctl=[('lk-d','Distance between genes (map units)',0,50,1,12),('lk-n','Offspring counted',100,2000,50,1000)],
   out=[('lk-par','parental offspring','x'),('lk-rec','recombinant offspring','a'),('lk-f','recombination frequency','v')],own=True),
  lab('lk-lab2','Order three genes',canvas='lk-canvas2',aria='A chromosome with three genes at chosen positions and the recombination frequency between each pair.',
   ctl=[('lk-pa','Position of gene A',0,60,1,5),('lk-pb','Position of gene B',0,60,1,15),('lk-pc','Position of gene C',0,60,1,21)],
   out=[('lk-ab','A–B','x'),('lk-bc','B–C','a'),('lk-ac','A–C','v'),('lk-ord','gene order','')],own=True)],
 [('Set the distance to 12 map units. What fraction of offspring are recombinants? <button type="button" class="btn link" data-show=\'' + show(["#lk-d",12],["#lk-n",1000]) + '\'>Set it up for me</button>','','About 12% (120 of 1000), split evenly between the two recombinant types.'),
  ('Set the distance to 50. What do you notice? <button type="button" class="btn link" data-show=\'' + show(["#lk-d",50]) + '\'>Set it up for me</button>','','Half the offspring are recombinants: the four classes are equal, just like independent assortment.')],
 ('In a test cross, 1,000 offspring are produced: 440 AB, 440 ab, 60 Ab and 60 aB. Find the distance between the genes.',[
  '<b>Recombinants.</b> Ab and aB are recombinants: 60 + 60 = 120.',
  '<b>Frequency.</b> 120/1000 = 0.12 = 12%.',
  '<b>Map distance.</b> 12 map units.']),
 ['Counting parental types as recombinants.','Forgetting that the recombination frequency cannot exceed 50%.','Using the wrong total.','Saying genes at 50% recombination are on different chromosomes (they could be far apart on one).','Adding map distances without checking the order.'],
 ('Mapping three genes',['The two most distant genes have the largest recombination frequency, and it is close to the sum of the other two: A–B 10, B–C 6, A–C 16 means order A, B, C. Check that the largest equals the sum of the other two (approximately).']),
 [('Two genes show 5% recombination. How far apart are they?',['5 map units','50 map units','0.5 map units','They are unlinked'],0,'1% recombination = 1 map unit.')])
